package com.civic.controller; import com.civic.dto.*; import com.civic.entity.*; import com.civic.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/petitions") @RequiredArgsConstructor public class PetitionReviewController {private final PetitionRepository petitions;private final PetitionReviewRepository reviews;private final SignatureRepository signatures;private final UserRepository users;
 @PostMapping("/{id}/reviews") @PreAuthorize("hasRole('CITIZEN')") public ReviewResponse add(@PathVariable Long id,@RequestBody ReviewRequest r){User u=me();Petition p=petitions.findById(id).orElseThrow(()->new RuntimeException("Petition not found"));if(p.getStatus()!=com.civic.enums.PetitionStatus.UNDER_REVIEW)throw new RuntimeException("Petition is not ready for review");if(!signatures.existsByPetitionAndUser(p,u))throw new RuntimeException("Only petition signers can review");if(reviews.existsByPetitionAndCitizen(p,u))throw new RuntimeException("You have already reviewed this petition");PetitionReview x=reviews.save(PetitionReview.builder().petition(p).citizen(u).rating(r.getRating()).description(r.getDescription()).build());return map(x);}
 @GetMapping("/{id}/reviews") public Map<String,Object> all(@PathVariable Long id){Petition p=petitions.findById(id).orElseThrow(()->new RuntimeException("Petition not found"));List<PetitionReview> list=reviews.findByPetitionOrderByCreatedAtAsc(p);long positive=reviews.countByPetitionAndRatingGreaterThanEqual(p,4);return Map.of("reviews",list.stream().map(this::map).toList(),"total",list.size(),"positivePercentage",list.isEmpty()?0:Math.round(positive*10000.0/list.size())/100.0);}
 private User me(){return users.findByEmail(org.springframework.security.core.context.SecurityContextHolder.getContext().getAuthentication().getName()).orElseThrow(()->new RuntimeException("User not found"));} private ReviewResponse map(PetitionReview r){return ReviewResponse.builder().id(r.getId()).petitionId(r.getPetition().getId()).citizenName(r.getCitizen().getName()).rating(r.getRating()).description(r.getDescription()).createdAt(r.getCreatedAt()).build();}
}
